package com.example.login;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

/**
 * Entry point for the LOGIN Spring Boot application.
 *
 * <p>Migrated from the COBOL LOGIN program (CICS/LOGIN/LOGIN-COB).
 * The original program received a user-id and password, verified credentials
 * against the EMPLO DB2 table via the CRYPTVE sub-program, then routed the
 * employee to the correct CICS map based on their department.
 *
 * <p>In the REST version the same business flow is exposed as a stateless
 * POST /api/login endpoint that returns a {@link com.example.login.dto.LoginResponse}
 * containing the routing decision and any relevant messages.
 */
@SpringBootApplication
public class Application {

    public static void main(String[] args) {
        SpringApplication.run(Application.class, args);
    }
}

