package com.example.login.model;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

import java.time.LocalDate;

/**
 * JPA entity that maps to the EMPLO DB2 table referenced in the original
 * COBOL program via {@code EXEC SQL INCLUDE EMPLO END-EXEC}.
 *
 * <p>Fields preserved from the COBOL host-variable declarations:
 * <ul>
 *   <li>EMPID   – PIC X(8)  → {@code String empId}</li>
 *   <li>ADMIDATE – PIC X(10) → {@code LocalDate admiDate}</li>
 *   <li>DEPTID  – PIC S9(9) COMP → {@code Integer deptId}</li>
 *   <li>PASSWORD – PIC X(8) (encrypted, stored by CRYPTVE) → {@code String encryptedPassword}</li>
 * </ul>
 */
@Entity
@Table(name = "emplo")
public class Employee {

    /** Employee identifier – maps to EMPID PIC X(8). */
    @Id
    @Column(name = "empid", length = 8, nullable = false)
    private String empId;

    /**
     * Admission / hire date – maps to ADMIDATE PIC X(10).
     * Stored as DATE in PostgreSQL.
     */
    @Column(name = "admidate", nullable = false)
    private LocalDate admiDate;

    /**
     * Department identifier – maps to DEPTID PIC S9(9) COMP.
     * Values used for routing:
     * 1 = CEO, 2/3/4 = CREW, 5 = HR, 6 = IT,
     * 7 = CUSTOMER_SERVICE (SRCHFLI), 8 = LAWYER, 9 = SCHEDULE.
     */
    @Column(name = "deptid", nullable = false)
    private Integer deptId;

    /**
     * Encrypted password produced by the CRYPTVE sub-program.
     * Stored as a BCrypt hash in the migrated system.
     */
    @Column(name = "encrypted_password", nullable = false)
    private String encryptedPassword;

    // -----------------------------------------------------------------
    // Constructors
    // -----------------------------------------------------------------

    protected Employee() {
        // JPA
    }

    public Employee(String empId, LocalDate admiDate, Integer deptId, String encryptedPassword) {
        this.empId = empId;
        this.admiDate = admiDate;
        this.deptId = deptId;
        this.encryptedPassword = encryptedPassword;
    }

    // -----------------------------------------------------------------
    // Accessors
    // -----------------------------------------------------------------

    public String getEmpId() {
        return empId;
    }

    public LocalDate getAdmiDate() {
        return admiDate;
    }

    public Integer getDeptId() {
        return deptId;
    }

    public String getEncryptedPassword() {
        return encryptedPassword;
    }
}

