package com.example.login.model;

/**
 * Enum that replaces the 88-level / EVALUATE WS-DEPT logic in paragraph
 * 0520-PROCESS-DATA of the original COBOL program.
 *
 * <p>Each constant carries the COBOL numeric code and the routing target
 * (CICS XCTL program name or descriptive message).
 */
public enum Department {

    CEO(1, "THE CEO MAP IS NOT AVAILABLE YET", null),
    CREW_FLIGHT(2, "THE CREW MAP IS NOT AVAILABLE YET", null),
    CREW_CABIN(3, "THE CREW MAP IS NOT AVAILABLE YET", null),
    CREW_GROUND(4, "THE CREW MAP IS NOT AVAILABLE YET", null),
    HR(5, "THE HR MAP IS NOT AVAILABLE YET", null),
    IT(6, "THE IT MAP IS NOT AVAILABLE YET", null),
    CUSTOMER_SERVICE(7, null, "SRCHFLI"),   // fully implemented – XCTL SRCHFLI
    LAWYER(8, "THE LAWYER MAP IS NOT AVAILABLE YET", null),
    SCHEDULE(9, "THE SCHEDULE MAP IS NOT AVAILABLE YET", null);

    private final int code;
    private final String unavailableMessage;
    private final String routingTarget;      // null when not yet implemented

    Department(int code, String unavailableMessage, String routingTarget) {
        this.code = code;
        this.unavailableMessage = unavailableMessage;
        this.routingTarget = routingTarget;
    }

    public int getCode() {
        return code;
    }

    public String getUnavailableMessage() {
        return unavailableMessage;
    }

    public String getRoutingTarget() {
        return routingTarget;
    }

    public boolean isImplemented() {
        return routingTarget != null;
    }

    /**
     * Resolves a numeric department code to the matching enum constant,
     * mirroring the EVALUATE WS-DEPT block in paragraph 0520-PROCESS-DATA.
     *
     * @param code the numeric DEPTID value from the EMPLO table
     * @return the matching {@link Department}
     * @throws IllegalArgumentException if the code is not recognised
     */
    public static Department fromCode(int code) {
        for (Department d : values()) {
            if (d.code == code) {
                return d;
            }
        }
        throw new IllegalArgumentException("Unknown department code: " + code);
    }
}

