package com.example.login.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * DTO for the incoming login request.
 *
 * <p>Maps to the LOGINMP map fields received by paragraph 0400-RECEIVE-MAP:
 * <ul>
 *   <li>USERIDI – PIC X(8) → {@code userId}</li>
 *   <li>PASSWI  – PIC X(8) → {@code password}</li>
 * </ul>
 *
 * @param userId   Employee user-id (max 8 characters, mirrors PIC X(8))
 * @param password Plain-text password supplied by the user (max 8 chars)
 */
public record LoginRequest(

        @NotBlank(message = "userId must not be blank")
        @Size(max = 8, message = "userId must be at most 8 characters")
        String userId,

        @NotBlank(message = "password must not be blank")
        @Size(max = 8, message = "password must be at most 8 characters")
        String password
) {}

