package com.example.login.dto;

import java.time.LocalDateTime;

/**
 * DTO for the login response returned to the caller.
 *
 * <p>Captures everything that the original COBOL program communicated back
 * through CICS map fields (MSG1O, MSG2O, LHOURO, LDATEO) and the COMMAREA
 * (TRANSACTION + USER-ID) that was passed to the next CICS program via XCTL.
 *
 * @param success        {@code true} when credentials are valid
 * @param userId         Echo of the authenticated user-id (mirrors USER-ID in WS-COMMAREA)
 * @param message1       Equivalent of MSG1O – primary status / routing message
 * @param message2       Equivalent of MSG2O – secondary error detail
 * @param routingTarget  Name of the next program/module to invoke (mirrors XCTL PROGRAM),
 *                       {@code null} when the map is not yet available
 * @param timestamp      Current date/time (replaces CICS ASKTIME + FORMATTIME output
 *                       written to LHOURO / LDATEO)
 * @param departmentCode Resolved DEPTID value for the authenticated employee
 */
public record LoginResponse(
        boolean success,
        String userId,
        String message1,
        String message2,
        String routingTarget,
        LocalDateTime timestamp,
        Integer departmentCode
) {}

