package com.example.login.repository;

import com.example.login.model.Employee;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import org.springframework.stereotype.Repository;

import java.util.Optional;

/**
 * Spring Data JPA repository for the {@link Employee} entity.
 *
 * <p>Replaces the EXEC SQL block in paragraph 0510-GET-LOGIN:
 * <pre>
 *   EXEC SQL
 *       SELECT ADMIDATE, DEPTID
 *       INTO :WS-ADMIDATE, :WS-DEPT
 *       FROM EMPLO
 *       WHERE EMPID = :WS-USERID
 *   END-EXEC.
 * </pre>
 */
@Repository
public interface EmployeeRepository extends JpaRepository<Employee, String> {

    /**
     * Retrieves an employee by their EMPID, projecting only the columns
     * needed by the login flow (ADMIDATE, DEPTID, ENCRYPTED_PASSWORD).
     *
     * <p>SQLCODE 0  → {@code Optional.of(employee)}<br>
     * SQLCODE 100 → {@code Optional.empty()} (NOT FOUND).<br>
     * Any other SQL exception is surfaced as a Spring
     * {@link org.springframework.dao.DataAccessException}.
     *
     * @param empId the employee identifier (maps to EMPID PIC X(8))
     * @return an {@link Optional} containing the employee if found
     */
    @Query("SELECT e FROM Employee e WHERE TRIM(e.empId) = TRIM(:empId)")
    Optional<Employee> findByEmpId(@Param("empId") String empId);
}

