package com.example.login.service;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.stereotype.Service;

import java.time.LocalDate;

/**
 * Java replacement for the CRYPTVE COBOL sub-program invoked in paragraph
 * 0510-GET-LOGIN via:
 * <pre>
 *   MOVE 'CRYPTVE' TO SUBPROGRAM
 *   CALL SUBPROGRAM USING WS-PASSWORD, WS-USERID, WS-ADMIDATE, WS-FLAG-LS.
 * </pre>
 *
 * <p>The original CRYPTVE program used a proprietary cryptographic scheme
 * seeded with the employee's admission date.  In the migrated system passwords
 * are stored as BCrypt hashes in the database and verified here using
 * Spring Security Crypto.
 *
 * <p>The interface of this service deliberately mirrors the COBOL CALL signature:
 * <ul>
 *   <li>{@code password}  – plain-text password entered by the user (WS-PASSWORD)</li>
 *   <li>{@code userId}    – employee identifier (WS-USERID)</li>
 *   <li>{@code admiDate}  – admission date from EMPLO (WS-ADMIDATE)</li>
 *   <li>{@code storedHash} – encrypted password stored in EMPLO (from CRYPTVE output)</li>
 * </ul>
 *
 * Returns a {@link VerifyResult} that maps to WS-FLAG-LS:
 * <ul>
 *   <li>{@code flagReturn == 0} – credentials OK</li>
 *   <li>{@code flagReturn == 1} – password / user-id mismatch</li>
 *   <li>{@code flagReturn == 2} – system / communication error</li>
 * </ul>
 */
@Service
public class CryptVerifyService {

    private static final Logger log = LoggerFactory.getLogger(CryptVerifyService.class);

    /**
     * Mirrors WS-FLAG-LS:
     * <pre>
     *   01 WS-FLAG-LS.
     *      02 WS-FLAG-RETURN  PIC X.
     *      02 WS-FLAG-ERROR   PIC X(10).
     * </pre>
     *
     * @param flagReturn 0 = OK, 1 = invalid credentials, 2 = system error
     * @param flagError  error code string (up to 10 chars), mirrors WS-FLAG-ERROR
     */
    public record VerifyResult(int flagReturn, String flagError) {
        /** Convenience factory – success. */
        static VerifyResult ok() {
            return new VerifyResult(0, "");
        }
        /** Convenience factory – credential mismatch. */
        static VerifyResult invalid() {
            return new VerifyResult(1, "");
        }
        /** Convenience factory – system error. */
        static VerifyResult systemError(String code) {
            // WS-FLAG-ERROR is PIC X(10) – pad/truncate to 10 chars
            String padded = String.format("%-10s", code).substring(0, 10);
            return new VerifyResult(2, padded);
        }
    }

    private final BCryptPasswordEncoder encoder;

    public CryptVerifyService() {
        this.encoder = new BCryptPasswordEncoder();
    }

    /**
     * Verifies a plain-text password against the stored BCrypt hash.
     *
     * <p>Directly replaces the COBOL CALL to CRYPTVE:
     * <pre>
     *   CALL SUBPROGRAM USING WS-PASSWORD, WS-USERID, WS-ADMIDATE, WS-FLAG-LS.
     * </pre>
     *
     * @param plainPassword the password entered by the user
     * @param userId        employee identifier (used for audit/logging)
     * @param admiDate      employee admission date (available for custom hash seeding
     *                      if the CRYPTVE algorithm is ever fully recovered)
     * @param storedHash    the BCrypt hash stored in the EMPLO.ENCRYPTED_PASSWORD column
     * @return a {@link VerifyResult} equivalent to WS-FLAG-LS after the CALL
     */
    public VerifyResult verify(String plainPassword,
                               String userId,
                               LocalDate admiDate,
                               String storedHash) {
        try {
            log.debug("CRYPTVE equivalent: verifying password for userId={}", userId);
            boolean matches = encoder.matches(plainPassword, storedHash);
            if (matches) {
                log.debug("Password verification succeeded for userId={}", userId);
                return VerifyResult.ok();          // WS-FLAG-RETURN = 0
            } else {
                log.debug("Password verification failed for userId={}", userId);
                return VerifyResult.invalid();     // WS-FLAG-RETURN = 1
            }
        } catch (Exception ex) {
            log.error("Unexpected error during password verification for userId={}", userId, ex);
            // WS-FLAG-RETURN = 2, WS-FLAG-ERROR = truncated exception code
            String errorCode = ex.getClass().getSimpleName();
            return VerifyResult.systemError(errorCode);
        }
    }

    /**
     * Encodes a plain-text password for storage – utility method used during
     * employee on-boarding (replaces CRYPTVE in write mode).
     *
     * @param plainPassword raw password
     * @return BCrypt hash suitable for storage in EMPLO.ENCRYPTED_PASSWORD
     */
    public String encode(String plainPassword) {
        return encoder.encode(plainPassword);
    }
}

