package com.example.login.service;

import org.springframework.stereotype.Service;

import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;

/**
 * Replacement for paragraphs 0100-GET-TIME and 0110-GIVING-TIME.
 *
 * <p>The original code used CICS ASKTIME + FORMATTIME to obtain the current
 * date and time and then applied an hour-adjustment:
 * <pre>
 *   IF WS-HOUR = 23
 *      MOVE ZEROS TO WS-HOUR
 *   ELSE
 *      ADD 1 TO WS-HOUR.
 *   END-IF
 * </pre>
 * This service reproduces that logic exactly.
 */
@Service
public class TimeService {

    /** Mirrors DATESEP('/') DDMMYYYY(WS-DATE) produced by CICS FORMATTIME. */
    private static final DateTimeFormatter DATE_FORMATTER =
            DateTimeFormatter.ofPattern("dd/MM/yyyy");

    /** Mirrors TIMESEP(':') TIME(WS-TIME) produced by CICS FORMATTIME. */
    private static final DateTimeFormatter TIME_FORMATTER =
            DateTimeFormatter.ofPattern("HH:mm:ss");

    /**
     * Obtains the current timestamp and applies the hour-roll logic from
     * paragraph 0110-GIVING-TIME.
     *
     * <p>COBOL logic faithfully reproduced:
     * <pre>
     *   IF WS-HOUR = 23
     *      MOVE ZEROS TO WS-HOUR   (i.e. roll to 00)
     *   ELSE
     *      ADD 1 TO WS-HOUR        (i.e. advance by one hour)
     *   END-IF
     * </pre>
     *
     * @return {@link AdjustedTime} containing the formatted date, time strings
     *         and the raw adjusted {@link LocalDateTime}
     */
    public AdjustedTime getCurrentAdjustedTime() {
        LocalDateTime now = LocalDateTime.now();

        // 0110-GIVING-TIME: adjust hour
        int adjustedHour;
        if (now.getHour() == 23) {
            adjustedHour = 0;                  // MOVE ZEROS TO WS-HOUR
        } else {
            adjustedHour = now.getHour() + 1;  // ADD 1 TO WS-HOUR
        }

        LocalDateTime adjusted = now.withHour(adjustedHour);

        return new AdjustedTime(
                adjusted.format(DATE_FORMATTER),   // LDATEO
                adjusted.format(TIME_FORMATTER),   // LHOURO
                adjusted
        );
    }

    /**
     * Carries the formatted date/time strings that the original COBOL
     * program moved into LDATEO and LHOURO map fields.
     *
     * @param formattedDate maps to LDATEO
     * @param formattedTime maps to LHOURO
     * @param adjustedDateTime the raw adjusted instant
     */
    public record AdjustedTime(
            String formattedDate,
            String formattedTime,
            LocalDateTime adjustedDateTime
    ) {}
}

