package com.example.login.service;

import com.example.login.dto.LoginRequest;
import com.example.login.dto.LoginResponse;
import com.example.login.model.Department;
import com.example.login.model.Employee;
import com.example.login.repository.EmployeeRepository;
import com.example.login.service.CryptVerifyService.VerifyResult;
import com.example.login.service.TimeService.AdjustedTime;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.dao.DataAccessException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.Optional;

/**
 * Core business-logic service for the LOGIN program.
 *
 * <p>This class directly replaces the PROCEDURE DIVISION paragraphs of the
 * original COBOL program.  The mapping is:
 * <ul>
 *   <li>MAIN-PARA             → {@link #processLogin(LoginRequest)}</li>
 *   <li>0500-PROCESS-LOGIN    → {@link #processLogin(LoginRequest)} (orchestrator)</li>
 *   <li>0510-GET-LOGIN        → {@link #getLoginData(String, String)}</li>
 *   <li>0520-PROCESS-DATA     → {@link #processData(int, String, Optional, VerifyResult)}</li>
 * </ul>
 *
 * <p>CICS pseudo-conversational state (EIBCALEN = 0 first-time vs. subsequent
 * interactions) is replaced by standard HTTP stateless semantics: every POST
 * to /api/login is a "subsequent" interaction carrying both userId and password.
 */
@Service
@Transactional(readOnly = true)
public class LoginService {

    private static final Logger log = LoggerFactory.getLogger(LoginService.class);

    // -----------------------------------------------------------------------
    // WS-FLAG-RETURN equivalents (EVALUATE WS-FLAG-RETURN in 0520-PROCESS-DATA)
    // -----------------------------------------------------------------------
    private static final int FLAG_OK      = 0;   // credentials verified
    private static final int FLAG_INVALID = 1;   // user-id or password wrong
    private static final int FLAG_ERROR   = 2;   // system / DB error

    // Messages from 0520-PROCESS-DATA
    private static final String MSG_INVALID_CREDENTIALS =
            "PASSWORD OR USERID INCORRECT.";
    private static final String MSG_SYSTEM_ERROR =
            "COMMUNICATION ERROR IN THE SYSTEM CALL THE IT DEPT";
    private static final String MSG_ERROR_CODE_PREFIX =
            "COMMUNICATE THE FOLLOW CODE ERROR: ";

    private final EmployeeRepository employeeRepository;
    private final CryptVerifyService cryptVerifyService;
    private final TimeService timeService;

    public LoginService(EmployeeRepository employeeRepository,
                        CryptVerifyService cryptVerifyService,
                        TimeService timeService) {
        this.employeeRepository = employeeRepository;
        this.cryptVerifyService = cryptVerifyService;
        this.timeService = timeService;
    }

    // -----------------------------------------------------------------------
    // MAIN-PARA / 0500-PROCESS-LOGIN
    // -----------------------------------------------------------------------

    /**
     * Main entry point – orchestrates the full login flow.
     *
     * <p>Corresponds to MAIN-PARA (ELSE branch, i.e. EIBCALEN &gt; 0) and
     * paragraph 0500-PROCESS-LOGIN.
     *
     * @param request the credentials supplied by the caller
     * @return a {@link LoginResponse} describing the outcome
     */
    public LoginResponse processLogin(LoginRequest request) {
        log.debug("processLogin: userId={}", request.userId());

        // 0100-GET-TIME + 0110-GIVING-TIME
        AdjustedTime adjustedTime = timeService.getCurrentAdjustedTime();

        // 0510-GET-LOGIN
        GetLoginResult loginResult = getLoginData(request.userId(), request.password());

        // 0520-PROCESS-DATA
        return processData(
                loginResult.flagReturn(),
                request.userId(),
                loginResult.employee(),
                loginResult.verifyResult(),
                adjustedTime
        );
    }

    // -----------------------------------------------------------------------
    // 0510-GET-LOGIN
    // -----------------------------------------------------------------------

    /**
     * Retrieves employee data and verifies the password.
     *
     * <p>Paragraph 0510-GET-LOGIN:
     * <ol>
     *   <li>Move USERIDI → WS-USERID, PASSWI → WS-PASSWORD</li>
     *   <li>EXEC SQL SELECT ADMIDATE, DEPTID INTO :WS-ADMIDATE, :WS-DEPT
     *       FROM EMPLO WHERE EMPID = :WS-USERID END-EXEC</li>
     *   <li>EVALUATE SQLCODE<br>
     *       WHEN 0   → CALL CRYPTVE (verify password)<br>
     *       WHEN 100 → WS-FLAG-RETURN = 1 (not found)<br>
     *       WHEN OTHER → WS-FLAG-RETURN = 2 (system error)</li>
     * </ol>
     *
     * @param userId   plain user-id from the map (USERIDI)
     * @param password plain password from the map (PASSWI)
     * @return a {@link GetLoginResult} carrying the flag, optional employee and
     *         the verify result from CRYPTVE
     */
    private GetLoginResult getLoginData(String userId, String password) {

        // Trim to mirror PIC X(8) right-space-filled fields
        String trimmedUserId = userId.trim();

        Optional<Employee> employeeOpt;
        try {
            // EXEC SQL SELECT … FROM EMPLO WHERE EMPID = :WS-USERID
            employeeOpt = employeeRepository.findByEmpId(trimmedUserId);
        } catch (DataAccessException dax) {
            // SQLCODE OTHER → WS-FLAG-RETURN = 2
            log.error("DB access error during login for userId={}", trimmedUserId, dax);
            String errorCode = dax.getClass().getSimpleName();
            String flagError = String.format("%-10s", errorCode).substring(0, 10);
            return new GetLoginResult(
                    FLAG_ERROR,
                    Optional.empty(),
                    new VerifyResult(FLAG_ERROR, flagError)
            );
        }

        if (employeeOpt.isEmpty()) {
            // SQLCODE 100 (NOT FOUND) → WS-FLAG-RETURN = 1
            log.debug("Employee not found: userId={}", trimmedUserId);
            return new GetLoginResult(
                    FLAG_INVALID,
                    Optional.empty(),
                    VerifyResult.invalid()
            );
        }

        // SQLCODE 0 → MOVE 1 TO WS-FLAG-RETURN then CALL 'CRYPTVE'
        // Note: the COBOL sets WS-FLAG-RETURN=1 before calling CRYPTVE;
        // CRYPTVE is expected to set it to 0 on success.
        // We model this by letting CryptVerifyService return the final flag.
        Employee employee = employeeOpt.get();
        VerifyResult verifyResult = cryptVerifyService.verify(
                password,
                trimmedUserId,
                employee.getAdmiDate(),
                employee.getEncryptedPassword()
        );

        return new GetLoginResult(verifyResult.flagReturn(), employeeOpt, verifyResult);
    }

    // -----------------------------------------------------------------------
    // 0520-PROCESS-DATA
    // -----------------------------------------------------------------------

    /**
     * Analyses WS-FLAG-RETURN and WS-DEPT to build the response.
     *
     * <p>Paragraph 0520-PROCESS-DATA EVALUATE WS-FLAG-RETURN:
     * <ul>
     *   <li>WHEN 0 → EVALUATE WS-DEPT (route to correct map / module)</li>
     *   <li>WHEN 1 → 'PASSWORD OR USERID INCORRECT.'</li>
     *   <li>WHEN 2 → system error message + error code</li>
     * </ul>
     */
    private LoginResponse processData(int flagReturn,
                                      String userId,
                                      Optional<Employee> employeeOpt,
                                      VerifyResult verifyResult,
                                      AdjustedTime adjustedTime) {
        return switch (flagReturn) {
            case FLAG_OK -> {
                // WHEN 0: EVALUATE WS-DEPT
                Employee employee = employeeOpt.orElseThrow();
                yield routeByDepartment(userId, employee, adjustedTime);
            }
            case FLAG_INVALID ->
                // WHEN 1: 'PASSWORD OR USERID INCORRECT.'
                new LoginResponse(
                        false,
                        null,
                        MSG_INVALID_CREDENTIALS,
                        null,
                        null,
                        adjustedTime.adjustedDateTime(),
                        null
                );
            default -> {
                // WHEN 2: system error
                // MOVE 'COMMUNICATION ERROR IN THE SYSTEM CALL THE IT DEPT' TO MSG1O
                // MOVE 'COMMUNICATE THE FOLLOW CODE ERROR: ' TO MSG2O
                // MOVE WS-FLAG-ERROR TO MSG2O(37:10)
                String msg2 = MSG_ERROR_CODE_PREFIX + verifyResult.flagError();
                yield new LoginResponse(
                        false,
                        null,
                        MSG_SYSTEM_ERROR,
                        msg2,
                        null,
                        adjustedTime.adjustedDateTime(),
                        null
                );
            }
        };
    }

    /**
     * Performs the inner EVALUATE WS-DEPT routing logic from paragraph
     * 0520-PROCESS-DATA (WHEN 0 branch).
     *
     * <p>Department 7 (CUSTOMER_SERVICE) is the only fully-implemented route;
     * all others return an "not available" message, faithfully preserving the
     * original COBOL stubs.
     *
     * @param userId   the authenticated employee id (USERIDI → USER-ID in COMMAREA)
     * @param employee the full employee record
     * @param time     adjusted timestamp
     * @return a {@link LoginResponse} with routing information
     */
    private LoginResponse routeByDepartment(String userId,
                                            Employee employee,
                                            AdjustedTime time) {
        Department dept;
        try {
            dept = Department.fromCode(employee.getDeptId());
        } catch (IllegalArgumentException ex) {
            log.warn("Unknown department code {} for userId={}", employee.getDeptId(), userId);
            return new LoginResponse(
                    false,
                    userId,
                    "UNKNOWN DEPARTMENT CODE: " + employee.getDeptId(),
                    null,
                    null,
                    time.adjustedDateTime(),
                    employee.getDeptId()
            );
        }

        if (dept.isImplemented()) {
            // WHEN 7: EXEC CICS XCTL PROGRAM('SRCHFLI') COMMAREA(WS-COMMAREA)
            // In the REST world this means: return routing target to the caller
            log.info("Routing userId={} to program={}", userId, dept.getRoutingTarget());
            return new LoginResponse(
                    true,
                    userId,
                    null,
                    null,
                    dept.getRoutingTarget(),   // 'SRCHFLI'
                    time.adjustedDateTime(),
                    dept.getCode()
            );
        } else {
            // WHEN 1, 2, 3, 4, 5, 6, 8, 9 – map not yet available
            // MOVE USERIDI TO USER-ID
            // MOVE 'THE <DEPT> MAP IS NOT AVAILABLE YET' TO MSG1O
            log.info("Dept {} not yet available for userId={}", dept, userId);
            return new LoginResponse(
                    true,                          // authenticated OK
                    userId,
                    dept.getUnavailableMessage(),
                    null,
                    null,
                    time.adjustedDateTime(),
                    dept.getCode()
            );
        }
    }

    // -----------------------------------------------------------------------
    // Internal result carrier (replaces multiple WS-* working-storage fields)
    // -----------------------------------------------------------------------

    /**
     * Internal record that groups the outputs of paragraph 0510-GET-LOGIN:
     * WS-FLAG-RETURN, optional resolved Employee, and the CRYPTVE result.
     */
    private record GetLoginResult(
            int flagReturn,
            Optional<Employee> employee,
            VerifyResult verifyResult
    ) {}
}

