package com.example.login.controller;

import com.example.login.dto.LoginRequest;
import com.example.login.dto.LoginResponse;
import com.example.login.service.LoginService;
import com.example.login.service.TimeService;
import jakarta.validation.Valid;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

/**
 * REST controller that exposes the LOGIN program as an HTTP API.
 *
 * <p>Pseudo-conversational CICS flow → stateless REST:
 * <ul>
 *   <li>GET  /api/login  → returns welcome message + current adjusted time
 *       (mirrors the EIBCALEN = 0 first-time branch of MAIN-PARA).</li>
 *   <li>POST /api/login  → processes credentials and returns routing decision
 *       (mirrors the ELSE branch: RECEIVE-MAP → PROCESS-LOGIN → SEND-MAP).</li>
 * </ul>
 */
@RestController
@RequestMapping("/api/login")
public class LoginController {

    private static final String WELCOME_MESSAGE =
            "                 WELCOME TO COBOL AIRLINES SYSTEM";

    private final LoginService loginService;
    private final TimeService timeService;

    public LoginController(LoginService loginService, TimeService timeService) {
        this.loginService = loginService;
        this.timeService = timeService;
    }

    /**
     * Returns the welcome screen data (EIBCALEN = 0 branch of MAIN-PARA).
     *
     * <p>Equivalent to:
     * <pre>
     *   MOVE '... WELCOME TO COBOL AIRLINES SYSTEM' TO MSG1O
     *   PERFORM 0100-GET-TIME
     *   PERFORM 0110-GIVING-TIME
     *   PERFORM 0200-SEND-MAP
     * </pre>
     *
     * @return 200 OK with welcome payload
     */
    @GetMapping
    public ResponseEntity<LoginResponse> welcome() {
        TimeService.AdjustedTime time = timeService.getCurrentAdjustedTime();
        LoginResponse response = new LoginResponse(
                false,
                null,
                WELCOME_MESSAGE,
                null,
                null,
                time.adjustedDateTime(),
                null
        );
        return ResponseEntity.ok(response);
    }

    /**
     * Processes login credentials (ELSE branch of MAIN-PARA).
     *
     * <p>Equivalent to:
     * <pre>
     *   PERFORM 0400-RECEIVE-MAP
     *   PERFORM 0500-PROCESS-LOGIN
     *   PERFORM 0100-GET-TIME
     *   PERFORM 0110-GIVING-TIME
     *   PERFORM 0200-SEND-MAP
     * </pre>
     *
     * @param request validated login credentials
     * @return 200 OK on successful authentication (even if routing target
     *         is not yet implemented), 401 UNAUTHORIZED on bad credentials,
     *         502 BAD_GATEWAY on system error.
     */
    @PostMapping
    public ResponseEntity<LoginResponse> login(@Valid @RequestBody LoginRequest request) {
        LoginResponse response = loginService.processLogin(request);

        HttpStatus status = switch (response.message1()) {
            case String m when m != null && m.contains("INCORRECT") ->
                    HttpStatus.UNAUTHORIZED;
            case String m when m != null && m.contains("COMMUNICATION ERROR") ->
                    HttpStatus.BAD_GATEWAY;
            default -> HttpStatus.OK;
        };

        return ResponseEntity.status(status).body(response);
    }
}

