package com.example.login.config;

import com.example.login.dto.LoginResponse;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.validation.FieldError;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

import java.time.LocalDateTime;
import java.util.stream.Collectors;

/**
 * Global exception handler – maps uncaught exceptions to structured
 * {@link LoginResponse} payloads with appropriate HTTP status codes.
 *
 * <p>In the original COBOL program, unexpected errors were signalled by
 * setting WS-FLAG-RETURN = 2 and writing to MSG1O / MSG2O.  This class
 * reproduces that pattern for the REST layer.
 */
@RestControllerAdvice
public class GlobalExceptionHandler {

    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    /**
     * Handles Jakarta Validation errors (e.g. blank userId / password).
     * Maps to the implicit input-validation the CICS map would perform.
     */
    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<LoginResponse> handleValidation(MethodArgumentNotValidException ex) {
        String details = ex.getBindingResult().getFieldErrors().stream()
                .map(FieldError::getDefaultMessage)
                .collect(Collectors.joining("; "));
        log.warn("Validation failed: {}", details);
        LoginResponse body = new LoginResponse(
                false,
                null,
                "INPUT VALIDATION ERROR: " + details,
                null,
                null,
                LocalDateTime.now(),
                null
        );
        return ResponseEntity.badRequest().body(body);
    }

    /**
     * Catches all unhandled exceptions and maps them to the
     * "COMMUNICATION ERROR" message (WS-FLAG-RETURN = 2 equivalent).
     */
    @ExceptionHandler(Exception.class)
    public ResponseEntity<LoginResponse> handleGeneral(Exception ex) {
        log.error("Unhandled exception in LOGIN service", ex);
        String errorCode = String.format("%-10s", ex.getClass().getSimpleName()).substring(0, 10);
        LoginResponse body = new LoginResponse(
                false,
                null,
                "COMMUNICATION ERROR IN THE SYSTEM CALL THE IT DEPT",
                "COMMUNICATE THE FOLLOW CODE ERROR: " + errorCode,
                null,
                LocalDateTime.now(),
                null
        );
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(body);
    }
}
